//----------------------------------------------------------------------------
// Two little spec‐functions to count `true` entries:

#[verifier::spec]
fn count_true(cond: Seq<bool>) -> nat {
    // total number of `true` in the whole sequence
    cond.iter().fold(0, |acc, &b| if b { acc + 1 } else { acc })
}

#[verifier::spec]
fn count_true_prefix(cond: Seq<bool>, prefix_len: nat) -> nat {
    // number of `true` in the first `prefix_len` elements
    cond[..prefix_len].iter().fold(0, |acc, &b| if b { acc + 1 } else { acc })
}

